	reg [7:0] irqlatch;
	reg [7:0] irqlatchL;
	reg irqM;
	reg irqE;
	reg irqA;
	wire [63:0] SS_MAP1;
	always @(posedge clk20)
		if (~enable)
			{irqM, irqA, irqlatch, irqlatchL} <= 0;
		else if (SaveStateBus_load) begin
			irqM <= SS_MAP1[0];
			irqA <= SS_MAP1[1];
			irqlatch <= SS_MAP1[9:2];
			irqlatchL <= SS_MAP1[36:29];
		end
		else if (ce && nesprg_we) begin
			if (irqlatch_add == 2'b11)
				irqlatch <= nesprgdin;
			else if (vrc5 && (irqlatch_add == 2'b10))
				irqlatchL <= nesprgdin;
			else if (irqlatch_add == 2'b10)
				irqlatch[7:4] <= nesprgdin[3:0];
			else if (irqlatch_add == 2'b01)
				irqlatch[3:0] <= nesprgdin[3:0];
			else if (irqctrl_add)
				{irqM, irqA} <= {nesprgdin[2], nesprgdin[0]};
		end
	reg [7:0] irqcnt;
	reg [7:0] irqcntL;
	reg timeout;
	reg [6:0] scalar;
	reg [1:0] line;
	wire irqclk = (vrc5 | irqM) | (scalar == 0);
	wire setE = (nesprg_we & irqctrl_add) & nesprgdin[1];
	always @(posedge clk20)
		if (~enable)
			{irqcnt, irqcntL, scalar, line} <= 0;
		else if (SaveStateBus_load) begin
			irqcnt <= SS_MAP1[17:10];
			scalar <= SS_MAP1[24:18];
			line <= SS_MAP1[26:25];
			irqcnt <= SS_MAP1[44:37];
		end
		else if (setE) begin
			scalar <= 113;
			line <= 0;
			irqcnt <= irqlatch;
			irqcntL <= irqlatchL;
		end
		else if (ce && irqE) begin
			if (scalar != 0)
				scalar <= scalar - 1'd1;
			else begin
				scalar <= (~line[1] ? 7'd113 : 7'd112);
				line <= (line[1] ? 2'd0 : line + 1'd1);
			end
			if (irqclk) begin
				if ((irqcnt == 255) && (!vrc5 | (irqcntL == 255))) begin
					irqcnt <= irqlatch;
					irqcntL <= irqlatchL;
				end
				else if (vrc5)
					{irqcnt, irqcntL} <= {irqcnt, irqcntL} + 1'd1;
				else
					irqcnt <= irqcnt + 1'd1;
			end
		end
	always @(posedge clk20)
		if (~enable) begin
			irqE <= 0;
			timeout <= 0;
		end
		else if (SaveStateBus_load) begin
			irqE <= SS_MAP1[27];
			timeout <= SS_MAP1[28];
		end
		else if (ce) begin
			if (nesprg_we & (irqctrl_add | irqack_add))
				timeout <= 0;
			else if ((irqclk & (irqcnt == 255)) && (!vrc5 | (irqcntL == 255)))
				timeout <= 1;
			if (nesprg_we & irqctrl_add)
				irqE <= nesprgdin[1];
			else if (nesprg_we & irqack_add)
				irqE <= irqA;
		end
	assign irq = timeout & irqE;
	wire [63:0] SS_MAP1_BACK;
	assign SS_MAP1_BACK[0] = irqM;
	assign SS_MAP1_BACK[1] = irqA;
	assign SS_MAP1_BACK[9:2] = irqlatch;
	assign SS_MAP1_BACK[17:10] = irqcnt;
	assign SS_MAP1_BACK[24:18] = scalar;
	assign SS_MAP1_BACK[26:25] = line;
	assign SS_MAP1_BACK[27] = irqE;
	assign SS_MAP1_BACK[28] = timeout;
	assign SS_MAP1_BACK[36:29] = irqlatchL;
	assign SS_MAP1_BACK[44:37] = irqcntL;
	assign SS_MAP1_BACK[63:45] = 19'b0000000000000000000;
	localparam [9:0] regs_savestates_SSREG_INDEX_L2MAP1 = 10'd40;
	eReg_SavestateV #(
		regs_savestates_SSREG_INDEX_L2MAP1,
		64'h0000000000000000
	) iREG_SAVESTATE_MAP1(
		clk20,
		SaveStateBus_Din,
		SaveStateBus_Adr,
		SaveStateBus_wren,
		SaveStateBus_rst,
		SaveStateBus_Dout,
		SS_MAP1_BACK,
		SS_MAP1
	);
endmodule
