module cart_vrc6sound (
	clk,
	ce,
	enable,
	wr,
	addr_invert,
	addr_in,
	din,
	outSq1,
	outSq2,
	outSaw,
	SaveStateBus_Din,
	SaveStateBus_Adr,
	SaveStateBus_wren,
	SaveStateBus_rst,
	SaveStateBus_load,
	SaveStateBus_Dout
);
	input clk;
	input ce;
	input enable;
	input wr;
	input addr_invert;
	input [15:0] addr_in;
	input [7:0] din;
	output wire [3:0] outSq1;
	output wire [3:0] outSq2;
	output wire [4:0] outSaw;
	input [63:0] SaveStateBus_Din;
	input [9:0] SaveStateBus_Adr;
	input SaveStateBus_wren;
	input SaveStateBus_rst;
	input SaveStateBus_load;
	output wire [63:0] SaveStateBus_Dout;
	wire [15:0] ain = (addr_invert ? {addr_in[15:2], addr_in[0], addr_in[1]} : addr_in);
	reg mode0;
	reg mode1;
	reg [3:0] vol0;
	reg [3:0] vol1;
	reg [5:0] vol2;
	reg [2:0] duty0;
	reg [2:0] duty1;
	reg [11:0] freq0;
	reg [11:0] freq1;
	reg [11:0] freq2;
	reg [11:0] div0;
	reg [11:0] div1;
	reg [12:0] div2;
	reg en0;
	reg en1;
	reg en2;
	reg [3:0] duty0cnt;
	reg [3:0] duty1cnt;
	reg [2:0] duty2cnt;
	reg [7:0] acc;
	wire [63:0] SS_MAP1;
	wire [63:0] SS_MAP2;
	always @(posedge clk)
		if (~enable) begin
			en0 <= 0;
			en1 <= 0;
			en2 <= 0;
		end
		else if (SaveStateBus_load) begin
			mode0 <= SS_MAP1[0];
			mode1 <= SS_MAP1[1];
			vol0 <= SS_MAP1[6:3];
			vol1 <= SS_MAP1[10:7];
			vol2 <= SS_MAP1[16:11];
			duty0 <= SS_MAP1[19:17];
			duty1 <= SS_MAP1[22:20];
			freq0 <= SS_MAP1[34:23];
			freq1 <= SS_MAP1[46:35];
			freq2 <= SS_MAP1[58:47];
			div0 <= SS_MAP2[11:0];
			div1 <= SS_MAP2[23:12];
			div2 <= SS_MAP2[36:24];
			en0 <= SS_MAP2[37];
			en1 <= SS_MAP2[38];
			en2 <= SS_MAP2[39];
			duty0cnt <= SS_MAP2[43:40];
			duty1cnt <= SS_MAP2[47:44];
			duty2cnt <= SS_MAP2[50:48];
			acc <= SS_MAP2[58:51];
		end
		else if (ce) begin
			if (wr)
				case (ain)
					16'h9000: {mode0, duty0, vol0} <= din;
					16'h9001: freq0[7:0] <= din;
					16'h9002: {en0, freq0[11:8]} <= {din[7], din[3:0]};
					16'ha000: {mode1, duty1, vol1} <= din;
					16'ha001: freq1[7:0] <= din;
					16'ha002: {en1, freq1[11:8]} <= {din[7], din[3:0]};
					16'hb000: vol2 <= din[5:0];
					16'hb001: freq2[7:0] <= din;
					16'hb002: {en2, freq2[11:8]} <= {din[7], din[3:0]};
				endcase
			if (en0) begin
				if (div0 != 0)
					div0 <= div0 - 1'd1;
				else begin
					div0 <= freq0;
					duty0cnt <= duty0cnt + 1'd1;
				end
			end
			if (en1) begin
				if (div1 != 0)
					div1 <= div1 - 1'd1;
				else begin
					div1 <= freq1;
					duty1cnt <= duty1cnt + 1'd1;
				end
			end
			if (en2) begin
				if (div2 != 0)
					div2 <= div2 - 1'd1;
				else begin
					div2 <= {freq2, 1'b1};
					if (duty2cnt == 6) begin
						duty2cnt <= 0;
						acc <= 0;
					end
					else begin
						duty2cnt <= duty2cnt + 1'd1;
						acc <= acc + vol2;
					end
				end
			end
		end
	wire [4:0] duty0pos = duty0cnt + {1'b1, ~duty0};
	wire [4:0] duty1pos = duty1cnt + {1'b1, ~duty1};
	wire [3:0] ch0 = ((~duty0pos[4] | mode0) & en0 ? vol0 : 4'd0);
	wire [3:0] ch1 = ((~duty1pos[4] | mode1) & en1 ? vol1 : 4'd0);
	wire [4:0] ch2 = (en2 ? acc[7:3] : 5'd0);
	assign outSq1 = ch0;
	assign outSq2 = ch1;
	assign outSaw = ch2;
	wire [63:0] SS_MAP1_BACK;
	assign SS_MAP1_BACK[0] = mode0;
	assign SS_MAP1_BACK[1] = mode1;
	assign SS_MAP1_BACK[6:3] = vol0;
	assign SS_MAP1_BACK[10:7] = vol1;
	assign SS_MAP1_BACK[16:11] = vol2;
	assign SS_MAP1_BACK[19:17] = duty0;
	assign SS_MAP1_BACK[22:20] = duty1;
	assign SS_MAP1_BACK[34:23] = freq0;
	assign SS_MAP1_BACK[46:35] = freq1;
	assign SS_MAP1_BACK[58:47] = freq2;
	assign SS_MAP1_BACK[63:59] = 5'b00000;
	wire [63:0] SS_MAP2_BACK;
	assign SS_MAP2_BACK[11:0] = div0;
	assign SS_MAP2_BACK[23:12] = div1;
	assign SS_MAP2_BACK[36:24] = div2;
	assign SS_MAP2_BACK[37] = en0;
	assign SS_MAP2_BACK[38] = en1;
	assign SS_MAP2_BACK[39] = en2;
	assign SS_MAP2_BACK[43:40] = duty0cnt;
	assign SS_MAP2_BACK[47:44] = duty1cnt;
	assign SS_MAP2_BACK[50:48] = duty2cnt;
	assign SS_MAP2_BACK[58:51] = acc;
	assign SS_MAP2_BACK[63:59] = 5'b00000;
	localparam SAVESTATE_MODULES = 2;
	wire [63:0] SaveStateBus_wired_or [0:1];
	wire [63:0] SaveStateBus_Dout_active = SaveStateBus_wired_or[0] | SaveStateBus_wired_or[1];
	localparam [9:0] regs_savestates_SSREG_INDEX_SNDMAP1 = 10'd48;
	eReg_SavestateV #(
		regs_savestates_SSREG_INDEX_SNDMAP1,
		64'h0000000000000000
	) iREG_SAVESTATE_MAP1(
		clk,
		SaveStateBus_Din,
		SaveStateBus_Adr,
		SaveStateBus_wren,
		SaveStateBus_rst,
		SaveStateBus_wired_or[0],
		SS_MAP1_BACK,
		SS_MAP1
	);
	localparam [9:0] regs_savestates_SSREG_INDEX_SNDMAP2 = 10'd49;
	eReg_SavestateV #(
		regs_savestates_SSREG_INDEX_SNDMAP2,
		64'h0000000000000000
	) iREG_SAVESTATE_MAP2(
		clk,
		SaveStateBus_Din,
		SaveStateBus_Adr,
		SaveStateBus_wren,
		SaveStateBus_rst,
		SaveStateBus_wired_or[1],
		SS_MAP2_BACK,
		SS_MAP2
	);
	assign SaveStateBus_Dout = (enable ? SaveStateBus_Dout_active : 64'h0000000000000000);
endmodule
module cart_Mapper89 (
	clk,
	ce,
	enable,
	flags,
	prg_ain,
	prg_aout_b,
