	chr_allow_b,
	vram_a10_b,
	vram_ce_b,
	irq_b,
	audio_in,
	audio_b,
	flags_out_b,
	SaveStateBus_Din,
	SaveStateBus_Adr,
	SaveStateBus_wren,
	SaveStateBus_rst,
	SaveStateBus_load,
	SaveStateBus_Dout
);
	input clk;
	input ce;
	input enable;
	input [31:0] flags;
	input [15:0] prg_ain;
	output wire [21:0] prg_aout_b;
	input prg_read;
	input prg_write;
	input [7:0] prg_din;
	output wire [7:0] prg_dout_b;
	output wire prg_allow_b;
	input [13:0] chr_ain;
	output wire [21:0] chr_aout_b;
	input chr_read;
	output wire chr_allow_b;
	output wire vram_a10_b;
	output wire vram_ce_b;
	output wire irq_b;
	input [15:0] audio_in;
	output wire [15:0] audio_b;
	output wire [15:0] flags_out_b;
	input [63:0] SaveStateBus_Din;
	input [9:0] SaveStateBus_Adr;
	input SaveStateBus_wren;
	input SaveStateBus_rst;
	input SaveStateBus_load;
	output wire [63:0] SaveStateBus_Dout;
	wire [21:0] prg_aout;
	assign prg_aout_b = (enable ? prg_aout : 22'h000000);
	assign prg_dout_b = (enable ? 8'hff : {8 {1'b1}});
	wire prg_allow;
	assign prg_allow_b = (enable ? prg_allow : 1'h0);
	wire [21:0] chr_aout;
	assign chr_aout_b = (enable ? chr_aout : 22'h000000);
	wire chr_allow;
	assign chr_allow_b = (enable ? chr_allow : 1'h0);
	reg vram_a10;
	assign vram_a10_b = (enable ? vram_a10 : 1'h0);
	wire vram_ce;
	assign vram_ce_b = (enable ? vram_ce : 1'h0);
	assign irq_b = (enable ? 1'b0 : 1'h0);
	reg [15:0] flags_out = 16'h0008;
	assign flags_out_b = (enable ? flags_out : 16'h0000);
	assign audio_b = (enable ? {1'b0, audio_in[15:1]} : 16'h0000);
	reg [2:0] prgsel;
	reg [3:0] chrsel0;
	reg [3:0] chrsel1;
	reg [2:0] prg_temp;
	reg [4:0] chr_temp;
	reg mirror;
	wire [7:0] mapper = flags[7:0];
	wire mapper89 = mapper == 8'd89;
	wire mapper93 = mapper == 8'd93;
	wire mapper184 = mapper == 8'd184;
	wire [63:0] SS_MAP1;
	always @(posedge clk)
		if (~enable) begin
			prgsel <= 3'b110;
			chrsel0 <= 4'b1111;
			chrsel1 <= 4'b1111;
		end
		else if (SaveStateBus_load) begin
			prgsel <= SS_MAP1[2:0];
			chrsel0 <= SS_MAP1[6:3];
			chrsel1 <= SS_MAP1[10:7];
			mirror <= SS_MAP1[11];
		end
		else if (ce) begin
			if ((prg_ain[15] & prg_write) & mapper89)
				{chrsel0[3], prgsel, mirror, chrsel0[2:0]} <= prg_din;
			else if ((prg_ain[15] & prg_write) & mapper93)
				prgsel <= prg_din[6:4];
			else if (((prg_ain[15:13] == 3'b011) & prg_write) & mapper184)
				{chrsel1[3:0], chrsel0[3:0]} <= {2'b01, prg_din[5:4], 1'b0, prg_din[2:0]};
		end
	wire [63:0] SS_MAP1_BACK;
	assign SS_MAP1_BACK[2:0] = prgsel;
	assign SS_MAP1_BACK[6:3] = chrsel0;
	assign SS_MAP1_BACK[10:7] = chrsel1;
	assign SS_MAP1_BACK[11] = mirror;
	assign SS_MAP1_BACK[63:12] = 52'b0000000000000000000000000000000000000000000000000000;
	always @(*) begin
		casez ({mapper89, flags[14]})
			2'b00: vram_a10 = {chr_ain[11]};
			2'b01: vram_a10 = {chr_ain[10]};
			2'b1z: vram_a10 = {mirror};
		endcase
		casez ({mapper184, prg_ain[14]})
			2'b00: prg_temp = {prgsel};
			2'b01: prg_temp = 3'b111;
			2'b1z: prg_temp = {2'b00, prg_ain[14]};
		endcase
		casez ({mapper184, chr_ain[12]})
			2'b0z: chr_temp = {chrsel0, chr_ain[12]};
			2'b10: chr_temp = {1'b0, chrsel0};
			2'b11: chr_temp = {1'b0, chrsel1};
		endcase
	end
	assign vram_ce = chr_ain[13];
	assign prg_aout = {5'b00000, prg_temp, prg_ain[13:0]};
	assign prg_allow = prg_ain[15] && !prg_write;
	assign chr_allow = flags[15];
	assign chr_aout = {5'b10000, chr_temp, chr_ain[11:0]};
	wire [63:0] SaveStateBus_Dout_active;
	localparam [9:0] regs_savestates_SSREG_INDEX_MAP1 = 10'd32;
	eReg_SavestateV #(
		regs_savestates_SSREG_INDEX_MAP1,
		64'h0000000000000000
	) iREG_SAVESTATE_MAP1(
		clk,
		SaveStateBus_Din,
		SaveStateBus_Adr,
		SaveStateBus_wren,
		SaveStateBus_rst,
		SaveStateBus_Dout_active,
		SS_MAP1_BACK,
		SS_MAP1
	);
	assign SaveStateBus_Dout = (enable ? SaveStateBus_Dout_active : 64'h0000000000000000);
endmodule
